// Bộ ảnh 9 quái nhí (vẽ bằng AI, đã tách nền + giữ thành phần chính mỗi ô,
// nén WebP nhúng base64 để đẩy GitHub trọn vẹn). Lưới 3x3, ô 440x440.
export const MONSTER_SHEET = 'data:image/webp;base64,';
export function monsterPos(i: number): string {
  const c = i % 3, r = Math.floor(i / 3);
  return `${c * 50}% ${r * 50}%`;
}
